import jax
import jax.numpy as jnp
import flax.linen as nn
from jax import jit
import optax
from typing import Tuple, Optional, Dict

# --- SELF-CONTAINED SUBMISSION ---

# ===== UTILS =====
def get_trunk_grads(loss_fn, params):
    grads = jax.grad(loss_fn)(params)
    trunk_keys = ['Conv_0', 'BottleneckBlock_0', 'Conv_1', 'BottleneckBlock_1']
    trunk_grads = {k: v for k, v in grads.items() if k in trunk_keys}
    return trunk_grads

# ===== Cells & Block =====
class ConvLSTMCellLN(nn.Module):
    features: int
    @nn.compact
    def __call__(self, carry, x):
        h,c=carry; gates=nn.Conv(4*self.features,(3,3),padding='SAME')(jnp.concatenate([x,h],axis=-1)); gates=nn.LayerNorm(epsilon=1e-5)(gates); i,f,g,o=jnp.split(gates,4,axis=-1); i,f,o=nn.sigmoid(i),nn.sigmoid(f),nn.sigmoid(o); g=jnp.tanh(g); c=f*c+i*g; h=o*jnp.tanh(c); return (h,c),h
class BottleneckBlock(nn.Module):
    features: int
    @nn.compact
    def __call__(self, x):
        y=nn.Conv(self.features//4,(1,1))(x); y=nn.relu(y); y=nn.Conv(self.features//4,(3,3),padding='SAME')(y); y=nn.relu(y); y=nn.Conv(self.features,(1,1))(y); return nn.relu(x+y)

# ===== Probe Network =====
class KronoNetV4_Probe(nn.Module):
    cnn_features_1: int; cnn_features_2: int; conv_lstm_features: int; dilation_rate: int; steps: int=2; alpha: float=0.0; use_ln: bool=False
    @nn.compact
    def __call__(self, x, done):
        B,H,W,_=x.shape; cnn_out=nn.Conv(self.cnn_features_1,(3,3),padding='SAME',kernel_dilation=self.dilation_rate)(x); cnn_out=nn.relu(cnn_out); cnn_out=BottleneckBlock(self.cnn_features_1)(cnn_out); cnn_out=nn.Conv(self.cnn_features_2,(3,3),padding='SAME',kernel_dilation=self.dilation_rate)(cnn_out); cnn_out=nn.relu(cnn_out); cnn_out=BottleneckBlock(self.cnn_features_2)(cnn_out); 
        if self.use_ln: cnn_out=nn.LayerNorm()(cnn_out)
        if self.alpha > 0: norm_cnn=nn.LayerNorm()(cnn_out); cnn_out=cnn_out+self.alpha*(norm_cnn-cnn_out)
        rnn_state=(jnp.zeros((B,H,W,self.conv_lstm_features)),jnp.zeros((B,H,W,self.conv_lstm_features))); h,c=rnn_state; lstm_cell=ConvLSTMCellLN(self.conv_lstm_features)
        for _ in range(self.steps): (h,c),h_out = lstm_cell((h,c),cnn_out)
        z_heads=jnp.einsum('bhwc,bhwn->bnc',h_out,nn.softmax(nn.Conv(2,(1,1))(h_out).reshape(B,H*W,2),axis=1).reshape(B,H,W,2)); z=z_heads.reshape((B,-1)); 
        z=nn.relu(nn.Dense(256)(z)); policy_logits=nn.Dense(4)(z); value=nn.Dense(1)(z).squeeze(-1); return policy_logits,value

# ===== Test Function =====
def test():
    key = jax.random.PRNGKey(42); batch_size=64; dummy_obs=jax.random.normal(key,(batch_size,8,8,8)); dummy_done=jnp.zeros(batch_size,dtype=bool)
    hparams = {'cnn_features_1':32,'cnn_features_2':64,'conv_lstm_features':96,'dilation_rate':6}

    configs = {
        "Baseline (No Norm)": {'use_ln': False, 'alpha': 0.0},
        "Simple LN":          {'use_ln': True, 'alpha': 0.0},
        "RIN (alpha=0.25)":   {'use_ln': False, 'alpha': 0.25},
    }

    print("--- Initial R_vp Probe on PPO Agent ---")
    for name, config in configs.items():
        network = KronoNetV4_Probe(**hparams, **config)
        key, init_key = jax.random.split(key)
        params = network.init(init_key, dummy_obs, dummy_done)['params']

        def policy_loss_fn(p):
            logits, _ = network.apply({'params': p}, dummy_obs, dummy_done)
            return -jnp.mean(nn.log_softmax(logits))

        def value_loss_fn(p):
            _, value = network.apply({'params': p}, dummy_obs, dummy_done)
            return jnp.mean(value**2)

        policy_grads_trunk = get_trunk_grads(policy_loss_fn, params)
        value_grads_trunk = get_trunk_grads(value_loss_fn, params)

        policy_norm = jnp.sqrt(sum([jnp.sum(g**2) for g in jax.tree_util.tree_leaves(policy_grads_trunk)]))
        value_norm = jnp.sqrt(sum([jnp.sum(g**2) for g in jax.tree_util.tree_leaves(value_grads_trunk)]))

        r_vp = value_norm / (policy_norm + 1e-8)
        print(f"[{name}] R_vp = {r_vp:.4f}")

    return "Probe complete. Results printed to STDOUT."
